/* Indexes for reads that searched a whole table on every call, found by reading the code against every index in the repository. orders by stripe_session_id (the Stripe webhook's duplicate check, the receipt, success and thank you pages, a cart's sibling lines) and by stripe_payment_intent_id (refund and dispute webhooks); commerce_checkouts by receipt_token (a buyer's order page, its cancel button, a support case) and by session_fingerprint (the receipt of a cart a code made free); profiles by email (every paid checkout links the buyer's account by email, and the password reset and account checks ask the same); membership_invoices by order_id (the buyer's library); community_bookmarks by post_id (the community feed counts saves per post); community_feed_posts by space_id whatever the status (the community's Feed and Spaces pages in /app count the posts in each space). Nothing else changes: no row, column, rule or function. Each index is made only when its table is there and the index is not, with a notice naming what was skipped. A plain CREATE INDEX stops writes to its table while it builds, and the editor holds that until the whole paste ends: on a large orders, profiles or commerce_checkouts table run supabase/sql/RUN_HOT_PATH_INDEXES_CONCURRENTLY.sql first, line by line, and this part then finds every index made and takes no lock. Before it runs the app works the same, only slower as those tables grow. Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.orders') IS NULL THEN RAISE NOTICE 'orders_stripe_session_idx skipped: public.orders does not exist here'; RETURN; END IF; IF to_regclass('public.orders_stripe_session_idx') IS NOT NULL THEN RETURN; END IF; CREATE INDEX IF NOT EXISTS orders_stripe_session_idx ON public.orders (stripe_session_id) WHERE stripe_session_id IS NOT NULL; END $do$;
DO $do$ BEGIN IF to_regclass('public.orders') IS NULL THEN RAISE NOTICE 'orders_stripe_payment_intent_idx skipped: public.orders does not exist here'; RETURN; END IF; IF to_regclass('public.orders_stripe_payment_intent_idx') IS NOT NULL THEN RETURN; END IF; CREATE INDEX IF NOT EXISTS orders_stripe_payment_intent_idx ON public.orders (stripe_payment_intent_id) WHERE stripe_payment_intent_id IS NOT NULL; END $do$;
DO $do$ BEGIN IF to_regclass('public.commerce_checkouts') IS NULL THEN RAISE NOTICE 'commerce_checkouts_receipt_token_idx skipped: public.commerce_checkouts does not exist here'; RETURN; END IF; IF to_regclass('public.commerce_checkouts_receipt_token_idx') IS NOT NULL THEN RETURN; END IF; CREATE INDEX IF NOT EXISTS commerce_checkouts_receipt_token_idx ON public.commerce_checkouts (receipt_token) WHERE receipt_token IS NOT NULL; END $do$;
DO $do$ BEGIN IF to_regclass('public.commerce_checkouts') IS NULL THEN RAISE NOTICE 'commerce_checkouts_session_fingerprint_idx skipped: public.commerce_checkouts does not exist here'; RETURN; END IF; IF to_regclass('public.commerce_checkouts_session_fingerprint_idx') IS NOT NULL THEN RETURN; END IF; CREATE INDEX IF NOT EXISTS commerce_checkouts_session_fingerprint_idx ON public.commerce_checkouts (session_fingerprint) WHERE session_fingerprint IS NOT NULL; END $do$;
DO $do$ BEGIN IF to_regclass('public.profiles') IS NULL THEN RAISE NOTICE 'profiles_email_idx skipped: public.profiles does not exist here'; RETURN; END IF; IF to_regclass('public.profiles_email_idx') IS NOT NULL THEN RETURN; END IF; CREATE INDEX IF NOT EXISTS profiles_email_idx ON public.profiles (email); END $do$;
DO $do$ BEGIN IF to_regclass('public.membership_invoices') IS NULL THEN RAISE NOTICE 'membership_invoices_order_idx skipped: public.membership_invoices does not exist here (part 75)'; RETURN; END IF; IF to_regclass('public.membership_invoices_order_idx') IS NOT NULL THEN RETURN; END IF; CREATE INDEX IF NOT EXISTS membership_invoices_order_idx ON public.membership_invoices (order_id) WHERE order_id IS NOT NULL; END $do$;
DO $do$ BEGIN IF to_regclass('public.community_bookmarks') IS NULL THEN RAISE NOTICE 'community_bookmarks_post_idx skipped: public.community_bookmarks does not exist here (part 81)'; RETURN; END IF; IF to_regclass('public.community_bookmarks_post_idx') IS NOT NULL THEN RETURN; END IF; CREATE INDEX IF NOT EXISTS community_bookmarks_post_idx ON public.community_bookmarks (post_id); END $do$;
DO $do$ BEGIN IF to_regclass('public.community_feed_posts') IS NULL THEN RAISE NOTICE 'community_feed_posts_space_any_status_idx skipped: public.community_feed_posts does not exist here (part 81)'; RETURN; END IF; IF to_regclass('public.community_feed_posts_space_any_status_idx') IS NOT NULL THEN RETURN; END IF; CREATE INDEX IF NOT EXISTS community_feed_posts_space_any_status_idx ON public.community_feed_posts (space_id) WHERE space_id IS NOT NULL; END $do$;
notify pgrst, 'reload schema';
